import { chromium } from 'playwright';

const BASE='https://www.statesideqm.com';
const THEME='158561894555';
const routes=[
['Accessories','/collections/accessories-gifts-collectibles'],['Airsoft','/collections/airsoft-milsim'],['Apparel','/collections/apparel'],['Armed Forces Gear','/collections/armed-forces-gear'],['Art','/collections/art'],['Body Armor','/collections/body-armor-ballistic-protection'],['Books','/collections/literature'],['Child Safety','/collections/child-safety-shop'],['DIVE / SCUBA','/collections/dive-scuba'],['Firearm Accessories','/collections/firearm-accessories'],['First Aid','/collections/first-aid-medical-ifak'],['Flags','/collections/flags-patriotic-decor'],['Flashlights','/collections/flashlights-lighting'],['Footwear','/collections/footwear-gloves-eyewear'],['K9','/collections/k9-dog-gear'],['Knives','/collections/knives-axes-cutlery'],['Morale Patches','/collections/morale-patches-tactical-id'],['Outdoor','/collections/outdoor-preparedness-gear'],['Patriotic','/collections/patriotic-american-heritage'],['Safety Rescue','/collections/safety-rescue-climbing'],['Sta-Brite','/collections/sta-brite-insignia'],['Tactical Gear','/collections/tactical-gear'],['Thin Line','/collections/thin-line'],['Uniforms','/collections/uniforms'],['Watches','/collections/watches'],['Lighters','/collections/zippos-lighters-torches'],['Logo Merch','/collections/stateside-quartermaster-logo-merch'],['Army National Guard','/collections/army-national-guard-series'],['Air National Guard','/collections/air-national-guard-series'],['U.S. Army','/collections/products-built-for-the-line-u-s-army'],['U.S. Navy','/collections/products-built-for-the-line-u-s-navy'],['U.S. Air Force','/collections/products-built-for-the-line-u-s-air-force'],['U.S. Marines','/collections/products-built-for-the-line-u-s-marine-corps'],['U.S. Coast Guard','/collections/products-built-for-the-line-u-s-coast-guard'],['U.S. Space Force','/collections/products-built-for-the-line-u-s-space-force'],['ROTC','/collections/rotc-series'],['JROTC','/collections/jrotc-series'],['Military Schools','/collections/military-schools-academies'],['Law Enforcement','/collections/law-enforcement-corrections'],['Fire EMS SAR','/collections/firefighting-ems-search-rescue']];

const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function preview(path,extra={}){const u=new URL(path,BASE);u.searchParams.set('preview_theme_id',THEME);for(const[k,v]of Object.entries(extra))u.searchParams.set(k,v);return u.toString()}
async function go(page,path,extra={}){let last;for(let i=0;i<5;i++){try{const r=await page.goto(preview(path,extra),{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200){await settle(page);return r}last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep([3500,6000,9000,13000,18000][i])}throw last||new Error('navigation failed')}
async function settle(page){await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await page.waitForFunction(()=>{const m=document.querySelector('#MainContent');const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};if(!m||![...m.querySelectorAll('.sq-refine-v3-sidebar')].some(vis))return false;return [...m.querySelectorAll('.sq-refine-v3-results .product-grid')].some(g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]')))},null,{timeout:45000});await sleep(900)}
async function snap(page){return page.evaluate(()=>{const m=document.querySelector('#MainContent');const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const sides=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis);const legacy=[...m.querySelectorAll('.sq-global-refine-sidebar,.sq-collection-sidebar,.facets-block-wrapper,.facets-container,.facets-wrapper,[class*="filter-sidebar"]')].filter(e=>vis(e)&&!e.classList.contains('sq-refine-v3-sidebar'));const grids=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const has=g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]'));const g=grids.find(x=>x.classList.contains('sq-v3-authoritative-grid')&&has(x))||grids.find(has);const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];const rs=cards.slice(0,12).map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4):[];const s=sides[0],t=s?.querySelector('.sq-refine-v3-sidebar__title'),sr=s?.getBoundingClientRect(),tr=t?.getBoundingClientRect();const groups=s?[...s.querySelectorAll(':scope > details.sq-refine-v3-group')].map(d=>({label:(d.querySelector(':scope > summary')?.textContent||'').trim(),inputs:d.querySelectorAll('input[type=checkbox]').length,targets:[...d.querySelectorAll('input[data-kind=structural][data-target]')].map(i=>i.dataset.target||'')})):[];return{v3:sides.length,legacy:legacy.length,position:s?getComputedStyle(s).position:'',title:(t?.textContent||'').trim(),titleBg:t?getComputedStyle(t).backgroundColor:'',sideBg:s?getComputedStyle(s).backgroundColor:'',gap:sr&&tr?Math.max(0,sr.right-tr.right):999,cards:cards.length,row:row.length,width:row.length?Math.round(row.map(r=>r.width).sort((a,b)=>a-b)[Math.floor(row.length/2)]):0,groups,pageSizes:[...m.querySelectorAll('.sq-refine-v3-page-size input')].map(i=>i.value)}})}
function baseErrors(d){const e=[];if(d.v3!==1)e.push('V3 sidebars='+d.v3);if(d.legacy)e.push('legacy sidebars='+d.legacy);if(d.position!=='sticky')e.push('sidebar '+d.position);if(d.title.toUpperCase()!=='REFINE PRODUCTS'||d.titleBg!=='rgb(8, 40, 63)'||d.sideBg!=='rgb(8, 40, 63)'||d.gap>1.5)e.push('header edge/color');if(d.cards<1)e.push('no visible products');if(d.row!==3)e.push('desktop row='+d.row);if(d.width<250)e.push('card width='+d.width);if(d.pageSizes.join(',')!=='50,100,250')e.push('page sizes='+d.pageSizes.join(','));for(const g of d.groups){if(!g.inputs)e.push('empty '+g.label);for(const x of g.targets){if(!x.startsWith('/collections/'))e.push('bad structural target '+g.label);else if(!new URL(x,BASE).searchParams.get('sq_root'))e.push('missing sq_root '+g.label)}}return e}

const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const page=await ctx.newPage();const failures=[];const pageErrors=[];page.on('pageerror',e=>{if(/sq-refine|sq-v3/i.test(e.stack||e.message||''))pageErrors.push(e.message)});

for(let i=0;i<routes.length;i++){const[n,path]=routes[i];try{await go(page,path);const d=await snap(page);const e=baseErrors(d);if(path==='/collections/literature'){const labels=d.groups.map(x=>x.label);for(const req of ['Shop by Publisher','Shop by War / Era / Conflict','Shop by Branch','Shop by Topic'])if(!labels.some(x=>x===req||x.startsWith(req)))e.push('missing '+req);const a=d.groups.find(x=>x.label==='Shop by Author');if(a)e.push('unsafe Author group still visible')}if(path==='/collections/firearm-accessories'&&!d.groups.some(x=>x.label==='Shop by Make / Model'))e.push('missing Make/Model');if(e.length)failures.push(n+': '+e.join(' | '));console.log((e.length?'FAIL ':'PASS ')+(i+1)+'/40 '+n+(e.length?' :: '+e.join(' | '):''))}catch(e){failures.push(n+': '+String(e));console.log('FAIL '+n+' :: '+e)}await sleep(700)}

// Protected non-V3 routes.
for(const [name,path] of [['State Guard','/collections/state-guard-series'],['Armored Vehicles','/pages/armored-vehicles-purchase-inquiry']]){try{const r=await page.goto(preview(path),{waitUntil:'domcontentloaded',timeout:90000});await sleep(1200);const x=await page.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')}));if(r?.status()!==200||x.v3||x.side)failures.push(name+' protection '+JSON.stringify(x));console.log('PROTECTED '+name+' '+JSON.stringify(x))}catch(e){failures.push(name+' '+String(e))}}

// Disclosure and product-link/back behavior.
for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel','/collections/firearm-accessories','/collections/products-built-for-the-line-u-s-navy']){try{await go(page,path);const groups=page.locator('.sq-refine-v3-sidebar details.sq-refine-v3-group');const count=await groups.count();let tested=false;for(let i=0;i<count;i++){const g=groups.nth(i);if(await g.locator('input[type=checkbox]').count()){const before=await g.getAttribute('open');await g.locator(':scope > summary').click();await sleep(150);const after=await g.getAttribute('open');await g.locator(':scope > summary').click();await sleep(150);const final=await g.getAttribute('open');if(before!==null||after===null||final!==null)failures.push(path+' disclosure toggle');tested=true;break}}if(!tested)failures.push(path+' no disclosure with controls');const product=page.locator('.sq-refine-v3-results .product-grid:visible .product-grid__item:visible a[href*="/products/"]').first();const href=await product.getAttribute('href');if(!href)throw new Error('no product link');await product.click();await page.waitForURL(/\/products\//,{timeout:30000});await page.goBack({waitUntil:'domcontentloaded',timeout:90000});await settle(page);if((await snap(page)).v3!==1)failures.push(path+' back navigation lost sidebar');console.log('DEEP PASS '+path)}catch(e){failures.push(path+' deep '+String(e))}}

// Native checkbox URL and persistence through reload.
for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel']){try{await go(page,path);const input=page.locator('.sq-refine-v3-sidebar input[data-kind=native][data-filter-name][data-filter-value]:not(:checked)').first();if(await input.count()){const name=await input.getAttribute('data-filter-name'),value=await input.getAttribute('data-filter-value');await input.check();await page.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(page);const u=new URL(page.url());if(!u.searchParams.getAll(name).includes(value))failures.push(path+' native filter URL');let sel=`.sq-refine-v3-sidebar input[data-kind=native][data-filter-name="${CSS.escape(name)}"][data-filter-value="${CSS.escape(value)}"]`;const checked=await page.locator(sel).first().isChecked().catch(()=>false);if(!checked)failures.push(path+' native filter state after navigation');await page.reload({waitUntil:'domcontentloaded',timeout:90000});await settle(page);const checked2=await page.locator(sel).first().isChecked().catch(()=>false);if(!checked2)failures.push(path+' native filter state after reload');console.log('FILTER PASS '+path+' '+name+'='+value)}else console.log('FILTER SKIP '+path+' no native option')}catch(e){failures.push(path+' native '+String(e))}}

// Structural checkbox click must remain collection-scoped and preserve root.
for(const path of ['/collections/products-built-for-the-line-u-s-navy','/collections/literature']){try{await go(page,path);const input=page.locator('.sq-refine-v3-sidebar input[data-kind=structural][data-target^="/collections/"]').first();if(await input.count()){const target=await input.getAttribute('data-target');if(!new URL(target,BASE).searchParams.get('sq_root'))failures.push(path+' structural target missing sq_root');await input.check();await page.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(page);if(!page.url().includes('/collections/')||!new URL(page.url()).searchParams.get('sq_root'))failures.push(path+' structural navigation escaped root');if((await snap(page)).v3!==1)failures.push(path+' structural navigation lost sidebar');console.log('STRUCTURAL PASS '+path+' -> '+page.url())}else failures.push(path+' no structural option')}catch(e){failures.push(path+' structural '+String(e))}}

// Page-size controls must produce exactly requested rendered cards on large collection.
for(const size of ['50','100','250']){try{await go(page,'/collections/accessories-gifts-collectibles');const input=page.locator(`.sq-refine-v3-page-size input[value="${size}"]`);await input.check();await page.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(page);await sleep(size==='250'?2500:1200);if(new URL(page.url()).searchParams.get('sq_per_page')!==size)failures.push('page size '+size+' URL');const count=await page.locator('.sq-refine-v3-results .product-grid:visible .product-grid__item:visible').count();if(count!==Number(size))failures.push('page size '+size+' rendered '+count);console.log('PAGE-SIZE '+size+' count='+count)}catch(e){failures.push('page size '+size+' '+String(e))}}

// Mobile key routes: exactly one non-sticky sidebar and two columns.
const mobile=await browser.newContext({viewport:{width:390,height:844}});const mp=await mobile.newPage();for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel','/collections/literature','/collections/products-built-for-the-line-u-s-navy']){try{await go(mp,path);const d=await mp.evaluate(()=>{const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'};const m=document.querySelector('#MainContent'),s=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis),gs=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const has=g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]'));const g=gs.find(x=>x.classList.contains('sq-v3-authoritative-grid')&&has(x))||gs.find(has);const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')).slice(0,8):[];const rs=cards.map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;return{sidebars:s.length,position:s[0]?getComputedStyle(s[0]).position:'',row,cards:cards.length}});if(d.sidebars!==1||d.position==='sticky'||d.row!==2||d.cards<2)failures.push('mobile '+path+' '+JSON.stringify(d));console.log('MOBILE '+path+' '+JSON.stringify(d))}catch(e){failures.push('mobile '+path+' '+String(e))}}await mobile.close();

for(const e of pageErrors)failures.push('V3 pageerror '+e);
console.log('CUSTOMER-V2-SUMMARY '+JSON.stringify({routes:40,failures:failures.length,pageErrors:pageErrors.length}));for(const f of failures)console.log('FAILURE '+f);await ctx.close();await browser.close();if(failures.length)process.exit(1);
